import{describe,it,expect,vi}from"vitest";import{SpeechRecognitionAdapter}from"../../frontend/js-modules/voice/speech-recognition-adapter.js";function FakeRecognition(){this.start=vi.fn(),this.stop=vi.fn(()=>{this.onend&&this.onend()})}describe("SpeechRecognitionAdapter",()=>{it("reports an error and does not throw when no recognition constructor is available",()=>{const e=vi.fn(),t=new SpeechRecognitionAdapter({RecognitionCtor:null});t.onError(e);const n=t.start();expect(n).toBe(!1),expect(e).toHaveBeenCalledWith(expect.objectContaining({error:"unsupported"}))}),it("starts recognition and forwards final results",()=>{const e=vi.fn(),t=new SpeechRecognitionAdapter({RecognitionCtor:FakeRecognition,lang:"hi-IN"});t.onResult(e),t.start(),expect(t.recognition.lang).toBe("hi-IN");const n=Object.assign([{transcript:"namaste"}],{isFinal:!0});t.recognition.onresult({results:[n]}),expect(e).toHaveBeenCalledWith({transcript:"namaste",isFinal:!0})}),it("updates language on an active recognition instance",()=>{const e=new SpeechRecognitionAdapter({RecognitionCtor:FakeRecognition});e.start(),e.setLanguage("ta-IN"),expect(e.recognition.lang).toBe("ta-IN")}),it("stop() marks listening false and fires onEnd",()=>{const e=vi.fn(),t=new SpeechRecognitionAdapter({RecognitionCtor:FakeRecognition});t.onEnd(e),t.start(),t.stop(),expect(t.listening).toBe(!1),expect(e).toHaveBeenCalled()})});